/**
 * simulation-engine.ts — 组织仿真引擎 (ARCH-23 Phase C)
 *
 * 数字孪生的终极能力: 在本体图上运行 "what-if" 仿真。
 * Clone 图 → 应用变换 → 运行诊断 → 对比基线 → 生成建议。
 *
 * 关键设计决策: Clone, don't mutate-and-rollback.
 * 仿真在独立的 clone store 上运行，原始 store 完全不受影响。
 */
import { type GraphStore } from './graph-store';
import type { EdgeType, NodeType } from './types';
import { type GraphAlert } from './graph-monitor';
import { type DecisionAction } from './decision-engine';
export interface SimulationScenario {
    id: string;
    name: string;
    description: string;
    /** 图变换操作 */
    transformations: SimulationTransform[];
}
export type SimulationTransform = {
    type: 'add_node';
    nodeType: NodeType;
    props: Record<string, unknown>;
} | {
    type: 'remove_node';
    nodeId: string;
} | {
    type: 'add_edge';
    edgeType: EdgeType;
    from: string;
    to: string;
    weight: number;
} | {
    type: 'modify_edge';
    from: string;
    to: string;
    edgeType: EdgeType;
    newWeight: number;
} | {
    type: 'add_team';
    name: string;
    members: string[];
} | {
    type: 'restructure_team';
    teamId: string;
    addMembers?: string[];
    removeMembers?: string[];
};
export interface SimulationResult {
    scenarioId: string;
    scenarioName: string;
    /** 基线快照 ID */
    baselineSnapshotId: string;
    /** 仿真后快照 ID */
    simulatedSnapshotId: string;
    /** 图变化统计 */
    delta: {
        addedNodes: number;
        addedEdges: number;
        modifiedEdges: number;
    };
    /** 中心性变化 (关键人物影响力变化) */
    centralityChanges: Array<{
        nodeId: string;
        baseline: number;
        simulated: number;
        delta: number;
    }>;
    /** 社区结构变化 */
    communityChanges: {
        baselineCommunities: number;
        simulatedCommunities: number;
    };
    /** 触发的告警 (仿真后新出现的异常) */
    newAlerts: GraphAlert[];
    /** 触发的决策行动 */
    triggeredActions: DecisionAction[];
    /** 最短路径变化 (关键协作路径的效率变化) */
    pathChanges: Array<{
        from: string;
        to: string;
        baselineLength: number;
        simulatedLength: number;
        improved: boolean;
    }>;
    generatedAt: string;
}
/** 在图上运行仿真场景。原始 store 不会被修改。 */
export declare function runSimulation(store: GraphStore, graph: string, scenario: SimulationScenario): SimulationResult | null;
export declare function newHireScenario(personName: string, teamId: string): SimulationScenario;
export declare function restructureScenario(teamName: string, members: string[]): SimulationScenario;
